#!/usr/bin/env pwsh
$basedir=Split-Path $MyInvocation.MyCommand.Definition -Parent

$exe=""
$pathsep=":"
$env_node_path=$env:NODE_PATH
$new_node_path="D:\scamshield\node_modules\.pnpm\@capacitor+cli@8.5.3\node_modules\@capacitor\cli\bin\node_modules;D:\scamshield\node_modules\.pnpm\@capacitor+cli@8.5.3\node_modules\@capacitor\cli\node_modules;D:\scamshield\node_modules\.pnpm\@capacitor+cli@8.5.3\node_modules\@capacitor\node_modules;D:\scamshield\node_modules\.pnpm\@capacitor+cli@8.5.3\node_modules;D:\scamshield\node_modules\.pnpm\node_modules"
if ($PSVersionTable.PSVersion -lt "6.0" -or $IsWindows) {
  # Fix case when both the Windows and Linux builds of Node
  # are installed in the same directory
  $exe=".exe"
  $pathsep=";"
} else {
  $new_node_path="/mnt/d/scamshield/node_modules/.pnpm/@capacitor+cli@8.5.3/node_modules/@capacitor/cli/bin/node_modules:/mnt/d/scamshield/node_modules/.pnpm/@capacitor+cli@8.5.3/node_modules/@capacitor/cli/node_modules:/mnt/d/scamshield/node_modules/.pnpm/@capacitor+cli@8.5.3/node_modules/@capacitor/node_modules:/mnt/d/scamshield/node_modules/.pnpm/@capacitor+cli@8.5.3/node_modules:/mnt/d/scamshield/node_modules/.pnpm/node_modules"
}
if ([string]::IsNullOrEmpty($env_node_path)) {
  $env:NODE_PATH=$new_node_path
} else {
  $env:NODE_PATH="$new_node_path$pathsep$env_node_path"
}

$ret=0
if (Test-Path "$basedir/node$exe") {
  # Support pipeline input
  if ($MyInvocation.ExpectingInput) {
    $input | & "$basedir/node$exe"  "$basedir/../.pnpm/@capacitor+cli@8.5.3/node_modules/@capacitor/cli/bin/capacitor" $args
  } else {
    & "$basedir/node$exe"  "$basedir/../.pnpm/@capacitor+cli@8.5.3/node_modules/@capacitor/cli/bin/capacitor" $args
  }
  $ret=$LASTEXITCODE
} else {
  # Support pipeline input
  if ($MyInvocation.ExpectingInput) {
    $input | & "node$exe"  "$basedir/../.pnpm/@capacitor+cli@8.5.3/node_modules/@capacitor/cli/bin/capacitor" $args
  } else {
    & "node$exe"  "$basedir/../.pnpm/@capacitor+cli@8.5.3/node_modules/@capacitor/cli/bin/capacitor" $args
  }
  $ret=$LASTEXITCODE
}
$env:NODE_PATH=$env_node_path
exit $ret
